тных модулей',70,'','k-i6Pz_-t6A',NULL,'https://stepik.org/lesson/372098/step/1?unit=359652','',1),(198,'import-sobstvennyh-modulej-v-python','Импорт собственных модулей в Python',71,'','oSNc_ZRWNzI',NULL,'https://stepik.org/lesson/372099/step/1?unit=359653','',1),(199,'7-vidov-vyzyvaemyh-callable-obektov-v-python','7 видов вызываемых (callable) объектов в Python',72,'','To2Q7bRubHw',NULL,'https://stepik.org/lesson/435911/step/1?unit=426034','',1),(200,'metod-split-i-metod-join-python','Метод split и метод join Python',73,'','M5DB3Yun8gU',NULL,'','',1),(201,'pakety-v-python-fajl-__init__-peremennaya-__all__','Пакеты в Python. Файл __init__, переменная __all__',74,'','VCRxOdCueqM',NULL,'','',1),(202,'rabotaem-s-json-v-python-parsing-json-sohranyaem-j','Работаем с JSON в Python. Парсинг JSON, сохраняем JSON в файл',75,'','rIhygmw9HZM',NULL,'','',1),(203,'vvedenie-v-tkinter-pervaya-programma','Введение в Tkinter. Первая программа',1,'','mLySBcS-6p0',NULL,'','',7),(204,'vidzhet-label','Виджет Label',2,'','Ridn10uaq20',NULL,'','',7),(205,'vidzhet-button','Виджет Button',3,'','_pUeSkDMY6w',NULL,'','',7),(206,'metod-grid-raspolagaem-vidzhety-v-vide-tablicy','Метод grid, располагаем виджеты в виде таблицы',4,'','_7F6FsbJepo',NULL,'','',7),(207,'vidzhet-entry','Виджет Entry',5,'','5C7K5kCxyVM',NULL,'','',7),(208,'sozdaem-kalkulyator-na-tkinter','Создаем калькулятор на tkinter',6,'','WTlxKkM7n5I',NULL,'','',7),(209,'kak-sdelat-kalkulyator-na-python-chast-2','Как сделать Калькулятор на python Часть 2',7,'','AyhMY3KXDLg',NULL,'','',7),(210,'kak-sdelat-kalkulyator-na-python-chast-3','Как сделать Калькулятор на python Часть 3',8,'','Py4__v9TB68',NULL,'','',7),(211,'kak-sdelat-kalkulyator-na-python-chast-4','Как сделать Калькулятор на python Часть 4',9,'','wMq1Wg6kMpM',NULL,'','',7),(212,'vidzhet-checkbutton','Виджет CheckButton',10,'','pAhvrCnsZqs',NULL,'','',7),(213,'vidzhet-radiobutton','Виджет Radiobutton',11,'','-_jxvOkpERc',NULL,'','',7),(214,'vidzhet-combobox','Виджет Combobox',12,'','RRMZ0zo1J3c',NULL,'','',7),(215,'igra-saper-prevyu','Игра \"Сапер\". Превью',13,'','I4yl0VbXpA8',NULL,'','',7),(216,'igra-saper-sozdaem-igrovoe-pole','Игра \"Сапер\", создаем игровое поле',14,'','nWjrZtskIWs',NULL,'','',7),(217,'igra-saper-sozdaem-klass-mineswepper','Игра \"Сапер\", создаем класс MineSwepper',15,'','8W00I8-D1js',NULL,'','',7),(218,'igra-saper-klass-mybutton','Игра \"Сапер\", класс MyButton',16,'','8IxBw-yPhwg',NULL,'','',7),(219,'igra-saper-rasstavlyaem-miny','Игра \"Сапер\", расставляем мины',17,'','1TdtlronS2A',NULL,'','',7),(220,'igra-saper-obrabotka-nazhatiya-knopok','Игра \"Сапер\", обработка нажатия кнопок',18,'','99CzpHWKFNE',NULL,'','',7),(221,'igra-saper-sozdaem-barernye-elementy','Игра \"Сапер\", создаем барьерные элементы',19,'','E9lIYJoA_0Y',NULL,'','',7),(222,'igra-saper-podschityvaem-miny-vokrug','Игра \"Сапер\", подсчитываем мины вокруг',20,'','Ye9VSmJZqTo',NULL,'','',7),(223,'igra-saper-dobavlyaem-cvet','Игра \"Сапер\", добавляем цвет',21,'','djDxOukrkZs',NULL,'','',7),(224,'igra-saper-skryvaem-polya','Игра \"Сапер\", скрываем поля',22,'','eZXu_wRfnes',NULL,'','',7),(225,'igra-saper-obhod-v-shirinu','Игра \"Сапер\", Обход в ширину',23,'','ledbZ1CbENU',NULL,'','',7),(226,'igra-saper-sozdaem-koncovku-igry','Игра \"Сапер\", создаем концовку игры',24,'','M0IIDVQAfqE',NULL,'','',7),(227,'igra-saper-sozdaem-menyu-igry','Игра \"Сапер\", создаем меню игры',25,'','ad9Mi21Q_OM',NULL,'','',7),(228,'igra-saper-perezapusk-igry','Игра \"Сапер\", перезапуск игры',26,'','7V3Vpm8Wfkw',NULL,'','',7),(229,'igra-saper-menyaem-nastrojki-igry','Игра \"Сапер\",  меняем настройки игры',28,'','yXIFSeh7LF4',NULL,'','',7),(230,'igra-saper-otmechaem-miny-na-pole','Игра \"Сапер\",   отмечаем мины на поле',29,'','pG95NWzlKaU',NULL,'','',7),(231,'znakomstvo-s-modulem-turtle','Знакомство с модулем Turtle',1,'','WIWHPDN7CTI',NULL,NULL,'модуль turtle,python turtle спираль,turtle python,turtle python круг,графика python,рисунки python,turtle python рисунки,питон turtle',4),(232,'risuem-pravilnie-mnogougolniki-turtrle','Рисуем правильные многоугольники turtrle',2,'','bRDG38an7a8',NULL,NULL,'черепашья графика python,turtle python квадрат,python turtle треугольник,как нарисовать треугольник в python,python,turtle python',4),(233,'kak-narisovat-zvezdu-turtle','Как нарисовать звезду turtle',3,'','d8FP3twpGKo',NULL,NULL,'как нарисовать звезду в pytho,как рисовать в python,как нарисовать звезду в питоне,python turtle нарисовать звезду,Рисование звезды python',4),(234,'kak-narisovat-zvezdnoe-nebo-turtle','Как нарисовать звездное небо turtle',4,'','Ml4a0Ddnmis',NULL,NULL,'как рисовать в python,как нарисовать звезду в питоне,нарисовать звездное небо python,как нарисовать звездное небо питон,как нарисовать звездное небо python',4),(235,'rasstavlyaem-zvezdi-na-nebe-turtle','Расставляем звезды на небе turtle',5,'','pLfOV9uQMM8',NULL,NULL,'событие turtle python,python turtle onclick event,python turtle event handler,python event loop,python обработка событий,python обработка событий turtle',4),(236,'obrabotka-sobitij-nazhatiya-na-klaviaturu-turtle','Обработка событий нажатия на клавиатуру turtle',6,'<h4>Обработка событий нажатия на клавиатуру turtle</h4>\r\n\r\n\r\n        <p>Текст реализованной программы (подробности смотрите в видео)</p>\r\n\r\n        <pre><code class=\" language-python\">import turtle\r\n\r\ndef moveUp():\r\n    x, y = pen.position()\r\n    pen.setposition(x, y + speed)\r\n\r\ndef moveDown():\r\n    x, y = pen.position()\r\n    pen.setposition(x, y - speed)\r\n\r\ndef moveRight():\r\n    x, y = pen.position()\r\n    pen.setposition(x + speed, y)\r\n\r\ndef moveLeft():\r\n    x, y = pen.position()\r\n    pen.setposition(x - speed, y)\r\n\r\ndef change():\r\n    if pen.isvisible():\r\n        pen.up()\r\n        pen.hideturtle()\r\n    else:\r\n        pen.down()\r\n        pen.showturtle()\r\n\r\ndef speedUP():\r\n    global speed\r\n    speed += 1\r\n\r\ndef speedDOWN():\r\n    global speed\r\n    speed = max(0, speed + 1)\r\n\r\nwindow = turtle.Screen()\r\npen = turtle.Turtle()\r\nspeed = 5\r\n\r\nwindow.onkey(moveUp, \"Up\")\r\nwindow.onkey(moveDown, \"Down\")\r\nwindow.onkey(moveRight, \"Right\")\r\nwindow.onkey(moveLeft, \"Left\")\r\nwindow.onkey(change, \"space\")\r\nwindow.onkey(speedUP, \"q\")\r\nwindow.onkey(speedDOWN, \"w\")\r\nwindow.listen()\r\nwindow.mainloop()</code></pre>','OcDH_jFQ7yc',NULL,NULL,'обработка нажатия клавиши python,проверка нажатия клавиши python,python считывание клавиш,события клавиатуры python,обработка нажатия клавиш python',4),(237,'risuem-olimpijskie-koltsa-turtle','Рисуем олимпийские кольца Turtle',7,'<p>&nbsp;&nbsp;&nbsp;&nbsp;<br></p>','PuMkCrRmWV0',NULL,NULL,'urtle python,модуль turtle python 3,рисование python,рисование в python,рисование в python turtle,python нарисовать,python черепашка',4),(238,'kak-zadat-sluchajnij-tsvet-v-turtle','Как задать случайный цвет в turtle',8,'<h4>Как задать случайный цвет в turtle</h4>\r\n\r\n        <p>Случайный цвет мы может получать из заранее созданного списка, в котором хранятся названия цветов. При\r\n        помощи функции choice из модуля random мы можем получить один элемент этого списка случайный образом.</p>\r\n\r\n        <p>Ниже представлен код, который каждую секунду меняет цвет экрана, а выбор цвета осуществляется случайным\r\n        образом из списка colors</p>\r\n\r\n        <pre><code class=\" language-python\">import turtle, random, time\r\n\r\ncolors = [\'red\', \'green\', \'yellow\', \'purple\', \'orange\']\r\n\r\nwindow = turtle.Screen()\r\n\r\nwhile True:\r\n    window.bgcolor(random.choice(colors))\r\n    time.sleep(1)\r\n\r\nwindow.mainloop()\r\n</code></pre>\r\n\r\n\r\n        <p> Но при такой реализации наш выбор цветов ограничен количеством элементов списка colors.</p>\r\n\r\n        <p> Другой способ задать случайный цвет, это передавать 3 величины в пределах от 0 до 1 в функцию bgcolor.\r\n        Первая величина обозначает красный цвет, вторая - зеленый и третья - синий. Таким образом мы пользуемся\r\n        моделью RGB(red green blue). Ниже программа, которая случайным образом задает цвет фона экрана.</p>\r\n\r\n\r\n\r\n        <pre><code class=\" language-python\">import turtle, random, time\r\n            \r\nwindow = turtle.Screen()\r\n\r\nwhile True:\r\n    red = random.random()\r\n    green = random.random()\r\n    blue = random.random()\r\n    window.bgcolor(red, green, blue)\r\n    time.sleep(1)\r\n\r\nwindow.mainloop()</code></pre>','SrTFTJr062c',NULL,NULL,'turtle python случайный цвет,turtle python изменить цвет,python цвета,python color,изменить цвет python,изменить color turtle python,случайный цвет python',4),(239,'prigayushchij-myachik-bounce-ball','Прыгающий мячик Bounce ball',9,'<h4>Прыгающий мячик Bounce ball</h4>\r\n\r\n\r\n        <p>Текст реализованной программы (подробности смотрите в видео)</p>\r\n\r\n        <pre><code class=\" language-python\">import turtle, random\r\n\r\nwindow = turtle.Screen()\r\nborder = turtle.Turtle()\r\nborder.speed(0)\r\nborder.up()\r\nborder.hideturtle()\r\nborder.pensize(5)\r\nborder.color(\'red\')\r\nborder.goto(300,300)\r\nborder.down()\r\nborder.goto(300,-300)\r\nborder.goto(-300,-300)\r\nborder.goto(-300,300)\r\nborder.goto(300,300)\r\n\r\nball = turtle.Turtle()\r\nball.hideturtle()\r\nball.shape(\'circle\')\r\nball.up()\r\nrandx = random.randint(-290,290)\r\nrandy = random.randint(-290,290)\r\nball.goto(randx,randy)\r\nball.showturtle()\r\ndx = 3\r\ndy = 2\r\n\r\nwhile True:\r\n    x,y = ball.position()\r\n    if x+dx >=300 or x+dx <= -300:\r\n        dx = -dx\r\n    if y+dy >=300 or y+dy <= -300:\r\n        dy = -dy\r\n    ball.goto(x+dx, y+dy)\r\n\r\nwindow.mainloop()</code></pre>','nGDCPL5TE2Y',NULL,NULL,'python движение turtle,turtle python примеры,bouncing ball game using python,bouncing ball game code in python,python простая игра,прыгающий мячик python',4),(240,'mnogo-prigayushchikh-myachikov','Много прыгающих мячиков',10,'','q0NE3YEil7I',NULL,NULL,'bounce ball game python,bouncing ball game python,bouncing ball game using python,bouncing ball game code in python,python простая игра,мини игры на python',4),(241,'myach-i-sila-prityazheniya','Мяч и сила притяжения',11,'<h4>Мяч-попрыгунчик и сила притяжения</h4>\r\n\r\n        <p>Ниже представлен код из видео</p>\r\n\r\n        <pre><code class=\" language-python\">import turtle\r\nborder = turtle.Turtle()\r\nborder.hideturtle()\r\nborder.speed(0)\r\nborder.pensize(5)\r\nborder.up()\r\nborder.goto(-250,250)\r\nborder.down()\r\nborder.goto(-250,-250)\r\nborder.goto(250,-250)\r\nborder.goto(250,250)\r\n\r\nball = turtle.Turtle(shape=\'circle\')\r\nball.up()\r\nball.goto(0,200)\r\nwindow = turtle.Screen()\r\nwindow.bgcolor(\'yellow\')\r\nball.speedY = 0\r\nball.speedX = -2\r\n\r\ngravitation = 0.1\r\n\r\nwhile True:\r\n    ball.speedY = ball.speedY - gravitation\r\n    ball.goto(ball.xcor()+ball.speedX, ball.ycor()+ball.speedY)\r\n\r\n    if ball.ycor() <= -250:\r\n        ball.speedY = -ball.speedY\r\n\r\n    if ball.xcor() >= 250 or ball.xcor() <= -250:\r\n        ball.speedX = -ball.speedX\r\n\r\nwindow.mainloop()</code></pre>','VCE5o91E-a4',NULL,NULL,'python мяч прыгун,python скачущий мяч,мяч попрыгун python,python,пишем игру на python,пишем простую игру на python,пишем простую графическую игру на python',4),(242,'mnogo-myachikov-i-sila-prityazheniya','Много мячиков и сила притяжения',12,'<h4>Много мячиков, прыгающий по воздествием притяжения</h4>\r\n\r\n        <p>Ниже представлен код из видео</p>\r\n\r\n        <pre><code class=\" language-python\">import turtle, random\r\nborder = turtle.Turtle()\r\nborder.hideturtle()\r\nborder.speed(0)\r\nborder.pensize(5)\r\nborder.up()\r\nborder.goto(-250,250)\r\nborder.down()\r\nborder.goto(-250,-250)\r\nborder.goto(250,-250)\r\nborder.goto(250,250)\r\n\r\nwindow = turtle.Screen()\r\nwindow.bgcolor(\'yellow\')\r\n\r\nballs = []\r\ncount = 5\r\nforms = [\'circle\', \'square\', \'triangle\', \'turtle\']\r\n\r\nfor i in range(count):\r\n    ball = turtle.Turtle(shape=random.choice(forms))\r\n    red = random.random()\r\n    green = random.random()\r\n    blue = random.random()\r\n    ball.color(red, green, blue)\r\n    ball.up()\r\n    ball.goto(random.randint(-200,200),random.randint(100,300))\r\n    ball.speedY = 0\r\n    ball.speedX = random.randint(-3,3)\r\n    balls.append(ball)\r\n\r\ngravitation = 0.1\r\n\r\nwhile True:\r\n    for ball in balls:\r\n        ball.speedY = ball.speedY - gravitation\r\n        ball.goto(ball.xcor()+ball.speedX, ball.ycor()+ball.speedY)\r\n\r\n        if ball.ycor() <= -250:\r\n            ball.speedY = -ball.speedY\r\n\r\n        if ball.xcor() >= 250 or ball.xcor() <= -250:\r\n            ball.speedX = -ball.speedX\r\n\r\nwindow.mainloop()</code></pre>','qH5ob8sK3bQ',NULL,NULL,'python игра обучение,учим python играя,игры на python примеры,turtle python примеры,гравитация turtle python,turtle python гравитация,python гравитация',4),(243,'uskoryaem-animatsiyu-pri-pomoshchi-funktsii-tracer','Ускоряем анимацию при помощи функции tracer',13,'<h4>Ускоряем анимацию при помощи функции tracer</h4>\r\n\r\n<p>Ниже представлен код из видео</p>\r\n\r\n<pre><code class=\" language-python\">import turtle, random\r\n\r\nborder = turtle.Turtle()\r\nborder.hideturtle()\r\nborder.speed(0)\r\nborder.pensize(5)\r\nborder.up()\r\nborder.goto(-250,250)\r\nborder.down()\r\nborder.goto(-250,-250)\r\nborder.goto(250,-250)\r\nborder.goto(250,250)\r\n\r\nwindow = turtle.Screen()\r\nwindow.bgcolor(\'yellow\')\r\nwindow.tracer(20)\r\n\r\nballs = []\r\ncount = 50\r\nforms = [\'circle\', \'square\', \'triangle\', \'turtle\']\r\n\r\nfor i in range(count):\r\n    ball = turtle.Turtle(shape=random.choice(forms))\r\n    red = random.random()\r\n    green = random.random()\r\n    blue = random.random()\r\n    ball.color(red, green, blue)\r\n    ball.up()\r\n    ball.goto(random.randint(-200,200),random.randint(100,300))\r\n    ball.speedY = 0\r\n    ball.speedX = random.randint(-3,3)\r\n    ball.angle = random.randint(-5,5)\r\n    ball.gravitation = random.randint(1,30)*0.01\r\n    balls.append(ball)\r\n\r\nwhile True:\r\n    window.update()\r\n    for ball in balls:\r\n\r\n        ball.left(ball.angle)\r\n        ball.speedY = ball.speedY - ball.gravitation\r\n        ball.goto(ball.xcor()+ball.speedX, ball.ycor()+ball.speedY)\r\n\r\n        if ball.ycor() &lt;= -250:\r\n            ball.sety(-250)\r\n            ball.speedY = -ball.speedY\r\n\r\n        if ball.xcor() &gt;= 250 or ball.xcor() &lt;= -250:\r\n            ball.speedX = -ball.speedX\r\n\r\nwindow.mainloop()</code></pre>','zcxekFk2I9w',NULL,NULL,'python,python модуль turtle,модуль turtle python 3,turtle в python,turtle в питоне,turtle питон,питон черепашка,питон программирование с нуля,питон программа',4),(244,'sozdaem-igru-ping-pong-na-python-chast-1','Создаем игру Пинг-Понг на Python. Часть 1',14,'<h4>Создаем игру Пинг-Понг на Python</h4>\r\n\r\n                <p>Код программы</p>\r\n\r\n                <pre class=\"line-numbers\"><code class=\"language-python\">import turtle\r\n\r\nwindow = turtle.Screen()\r\nwindow.title(\"Ping-Pong\")\r\nwindow.setup(width=1.0,height=1.0)\r\nwindow.bgcolor(\"black\")\r\n\r\nborder = turtle.Turtle()\r\nborder.speed(0)\r\nborder.color(\'green\')\r\nborder.begin_fill()\r\nborder.goto(-500,300)\r\nborder.goto(500,300)\r\nborder.goto(500,-300)\r\nborder.goto(-500,-300)\r\nborder.goto(-500,300)\r\nborder.end_fill()\r\n\r\nborder.goto(0,300)\r\nborder.color(\'white\')\r\nborder.setheading(270)\r\nfor i in range(25):\r\n    if i%2==0:\r\n        border.forward(24)\r\n    else:\r\n        border.up()\r\n        border.forward(24)\r\n        border.down()\r\nborder.hideturtle()\r\n\r\nwindow.mainloop()</code></pre>\r\n            </li>\r\n\r\n        </ol>','CbthqHzkd6U',NULL,NULL,'разработка игр, пинг понг питон, пинг понг на питоне код, игры на питоне, python игра обучение, python,python turtle game,turtle game python,ping pong python',4),(245,'sozdaem-igru-ping-pong-na-python-chast-2','Создаем игру Пинг-Понг на Python. Часть 2',15,'<h4>Создаем игру Пинг-Понг на Python</h4>\r\n<p>На предыдущем занятии мы создали программу, которая рисует стол для пинг-понга. А в этом видео мы создадим ракетку, которой можно управлять при нажатии клавиш. Подробности смотрите в видео</p>\r\n<p>Код получившейся программы:</p>\r\n\r\n<pre class=\"line-numbers\"><code class=\"language-python\">import turtle\r\n\r\nwindow = turtle.Screen()\r\nwindow.title(\"Ping-Pong\")\r\nwindow.setup(width=1.0,height=1.0)\r\nwindow.bgcolor(\"black\")\r\n\r\nborder = turtle.Turtle()\r\nborder.speed(0)\r\nborder.color(\'green\')\r\nborder.begin_fill()\r\nborder.goto(-500,300)\r\nborder.goto(500,300)\r\nborder.goto(500,-300)\r\nborder.goto(-500,-300)\r\nborder.goto(-500,300)\r\nborder.end_fill()\r\n\r\nborder.goto(0,300)\r\nborder.color(\'white\')\r\nborder.setheading(270)\r\nfor i in range(25):\r\n    if i%2==0:\r\n        border.forward(24)\r\n    else:\r\n        border.up()\r\n        border.forward(24)\r\n        border.down()\r\nborder.hideturtle()\r\n\r\nrocket_a = turtle.Turtle()\r\nrocket_a.color(\'white\')\r\nrocket_a.shape(\'square\')\r\nrocket_a.shapesize(stretch_len=1,stretch_wid=5)\r\nrocket_a.penup()\r\nrocket_a.goto(-450,0)\r\n\r\ndef move_up():\r\n     y  = rocket_a.ycor() + 10\r\n     if y > 250:\r\n         y = 250\r\n     rocket_a.sety(y)\r\n\r\n\r\ndef move_down():\r\n    y = rocket_a.ycor() - 10\r\n    if y < -250:\r\n        y = -250\r\n    rocket_a.sety(y)\r\n\r\nwindow.listen()\r\nwindow.onkeypress(move_up, \"w\")\r\nwindow.onkeypress(move_down, \"s\")\r\n\r\nwindow.mainloop()</code></pre>','jeHdY4Im9o0',NULL,NULL,'программирование игр на python,разработка игр на python,разработка игр,пинг понг питон,пинг понг на питоне код',4),(246,'sozdaem-igru-ping-pong-na-python-chast-3','Создаем игру Пинг-Понг на Python. Часть 3',16,'<h4>Создаем игру Пинг-Понг на Python</h4>\r\n<p>Ниже представлен текст программы, где реализованы две ракетки и их перемещение :</p>\r\n\r\n<pre class=\"line-numbers\"><code class=\"language-python\">import turtle\r\n\r\nwindow = turtle.Screen()\r\nwindow.title(\"Ping-Pong\")\r\nwindow.setup(width=1.0,height=1.0)\r\nwindow.bgcolor(\"black\")\r\n\r\nborder = turtle.Turtle()\r\nborder.speed(0)\r\nborder.color(\'green\')\r\nborder.begin_fill()\r\nborder.goto(-500,300)\r\nborder.goto(500,300)\r\nborder.goto(500,-300)\r\nborder.goto(-500,-300)\r\nborder.goto(-500,300)\r\nborder.end_fill()\r\n\r\nborder.goto(0,300)\r\nborder.color(\'white\')\r\nborder.setheading(270)\r\nfor i in range(25):\r\n    if i%2==0:\r\n        border.forward(24)\r\n    else:\r\n        border.up()\r\n        border.forward(24)\r\n        border.down()\r\nborder.hideturtle()\r\n\r\nrocket_a = turtle.Turtle()\r\nrocket_a.color(\'white\')\r\nrocket_a.shape(\'square\')\r\nrocket_a.shapesize(stretch_len=1,stretch_wid=5)\r\nrocket_a.penup()\r\nrocket_a.goto(-450,0)\r\n\r\nrocket_b = turtle.Turtle()\r\nrocket_b.speed(3)\r\nrocket_b.shape(\"square\")\r\nrocket_b.color(\"white\")\r\nrocket_b.shapesize(stretch_wid=5, stretch_len=1)\r\nrocket_b.penup()\r\nrocket_b.goto(450, 0)\r\n\r\ndef move_up():\r\n     y  = rocket_a.ycor() + 10\r\n     if y &gt; 250:\r\n         y = 250\r\n     rocket_a.sety(y)\r\n\r\n\r\ndef move_down():\r\n    y = rocket_a.ycor() - 10\r\n    if y &lt; -250:\r\n        y = -250\r\n    rocket_a.sety(y)\r\n\r\n\r\ndef move_up_b():\r\n    y = rocket_b.ycor() + 10\r\n    if y &gt; 250:\r\n        y = 250\r\n    rocket_b.sety(y)\r\n\r\n\r\ndef move_down_b():\r\n    y = rocket_b.ycor() - 10\r\n    if y &lt; -250:\r\n        y = -250\r\n    rocket_b.sety(y)\r\n\r\nwindow.listen()\r\nwindow.onkeypress(move_up, \"w\")\r\nwindow.onkeypress(move_down, \"s\")\r\nwindow.onkeypress(move_up_b, \"Up\")\r\nwindow.onkeypress(move_down_b, \"Down\")\r\n\r\nwindow.mainloop()</code></pre>','3P0lArajvu0',NULL,NULL,'программирование игр на python,разработка игр на python,разработка игр,пинг понг питон,пинг понг на питоне код',4),(247,'sozdaem-igru-ping-pong-na-python-chast-4','Создаем игру Пинг-Понг на Python. Часть 4',17,'<h4>Создаем игру Пинг-Понг на Python</h4>\r\n<p>Ниже представлен текст программы, где реализованы две ракетки и их перемещение :</p>\r\n\r\n<pre class=\"line-numbers\"><code class=\"language-python\">import turtle\r\nfrom random import choice, randint\r\n\r\nwindow = turtle.Screen()\r\nwindow.title(\"Ping-Pong\")\r\nwindow.setup(width=1.0,height=1.0)\r\nwindow.bgcolor(\"black\")\r\n\r\nborder = turtle.Turtle()\r\nborder.speed(0)\r\nborder.color(\'green\')\r\nborder.begin_fill()\r\nborder.goto(-500,300)\r\nborder.goto(500,300)\r\nborder.goto(500,-300)\r\nborder.goto(-500,-300)\r\nborder.goto(-500,300)\r\nborder.end_fill()\r\n\r\nborder.goto(0,300)\r\nborder.color(\'white\')\r\nborder.setheading(270)\r\nfor i in range(25):\r\n    if i%2==0:\r\n        border.forward(24)\r\n    else:\r\n        border.up()\r\n        border.forward(24)\r\n        border.down()\r\nborder.hideturtle()\r\n\r\nrocket_a = turtle.Turtle()\r\nrocket_a.color(\'white\')\r\nrocket_a.shape(\'square\')\r\nrocket_a.shapesize(stretch_len=1,stretch_wid=5)\r\nrocket_a.penup()\r\nrocket_a.goto(-450,0)\r\n\r\nrocket_b = turtle.Turtle()\r\nrocket_b.speed(3)\r\nrocket_b.shape(\"square\")\r\nrocket_b.color(\"white\")\r\nrocket_b.shapesize(stretch_wid=5, stretch_len=1)\r\nrocket_b.penup()\r\nrocket_b.goto(450, 0)\r\n\r\ndef move_up():\r\n     y  = rocket_a.ycor() + 10\r\n     if y > 250:\r\n         y = 250\r\n     rocket_a.sety(y)\r\n\r\n\r\ndef move_down():\r\n    y = rocket_a.ycor() - 10\r\n    if y < -250:\r\n        y = -250\r\n    rocket_a.sety(y)\r\n\r\n\r\ndef move_up_b():\r\n    y = rocket_b.ycor() + 10\r\n    if y > 250:\r\n        y = 250\r\n    rocket_b.sety(y)\r\n\r\n\r\ndef move_down_b():\r\n    y = rocket_b.ycor() - 10\r\n    if y < -250:\r\n        y = -250\r\n    rocket_b.sety(y)\r\n\r\nball = turtle.Turtle()\r\nball.shape(\'circle\')\r\nball.speed(0)\r\nball.color(\'red\')\r\nball.dx = 3\r\nball.dy = -3\r\nball.penup()\r\n\r\nwindow.listen()\r\nwindow.onkeypress(move_up, \"w\")\r\nwindow.onkeypress(move_down, \"s\")\r\nwindow.onkeypress(move_up_b, \"Up\")\r\nwindow.onkeypress(move_down_b, \"Down\")\r\n\r\nwhile True:\r\n    window.update()\r\n\r\n    ball.setx(ball.xcor() + ball.dx)\r\n    ball.sety(ball.ycor() + ball.dy)\r\n\r\n    if ball.ycor() >= 290:\r\n        ball.dy = -ball.dy\r\n\r\n    if ball.ycor() <= -290:\r\n        ball.dy = -ball.dy\r\n\r\n    if ball.xcor() >= 490:\r\n        ball.goto(0,randint(-150,150))\r\n        ball.dx = choice([-4,-3,-2, 2,3,4])\r\n        ball.dy = choice([-4,-3,-2, 2,3,4])\r\n\r\n    if ball.xcor() <= -490:\r\n        ball.goto(0,randint(-150,150))\r\n        ball.dx = choice([-4,-3,-2, 2,3,4])\r\n        ball.dy = choice([-4,-3,-2, 2,3,4])\r\n\r\nwindow.mainloop()</code></pre>','l25nSvtYLaY',NULL,NULL,'программирование игр на python,разработка игр на python,разработка игр,пинг понг питон,пинг понг на питоне код',4),(248,'sozdaem-igru-ping-pong-na-python-chast-5','Создаем игру Пинг-Понг на Python. Часть 5',18,'<h4>Создаем игру Пинг-Понг на Python</h4>\r\n<p>Ниже представлен текст программы, где реализованы две ракетки и их перемещение :</p>\r\n\r\n<pre class=\"line-numbers\"><code class=\"language-python\">import turtle\r\nfrom random import choice, randint\r\n\r\nwindow = turtle.Screen()\r\nwindow.title(\"Ping-Pong\")\r\nwindow.setup(width=1.0,height=1.0)\r\nwindow.bgcolor(\"black\")\r\nwindow.tracer(2)\r\n\r\n\r\nborder = turtle.Turtle()\r\nborder.speed(0)\r\nborder.color(\'green\')\r\nborder.begin_fill()\r\nborder.goto(-500,300)\r\nborder.goto(500,300)\r\nborder.goto(500,-300)\r\nborder.goto(-500,-300)\r\nborder.goto(-500,300)\r\nborder.end_fill()\r\n\r\nborder.goto(0,300)\r\nborder.color(\'white\')\r\nborder.setheading(270)\r\nfor i in range(25):\r\n    if i%2==0:\r\n        border.forward(24)\r\n    else:\r\n        border.up()\r\n        border.forward(24)\r\n        border.down()\r\nborder.hideturtle()\r\n\r\nrocket_a = turtle.Turtle()\r\nrocket_a.color(\'white\')\r\nrocket_a.shape(\'square\')\r\nrocket_a.shapesize(stretch_len=1,stretch_wid=5)\r\nrocket_a.penup()\r\nrocket_a.goto(-450,0)\r\n\r\nrocket_b = turtle.Turtle()\r\nrocket_b.speed(3)\r\nrocket_b.shape(\"square\")\r\nrocket_b.color(\"white\")\r\nrocket_b.shapesize(stretch_wid=5, stretch_len=1)\r\nrocket_b.penup()\r\nrocket_b.goto(450, 0)\r\n\r\nFONT = (\"Arial\", 44)\r\nscore_a = 0\r\ns1 = turtle.Turtle(visible=False)\r\ns1.color(\'white\')\r\ns1.penup()\r\ns1.setposition(-200, 300)\r\ns1.write(score_a, font=FONT)\r\n\r\nscore_b = 0\r\ns2 = turtle.Turtle(visible=False)\r\ns2.color(\'white\')\r\ns2.penup()\r\ns2.setposition(200, 300)\r\ns2.write(score_a, font=FONT)\r\n\r\ndef move_up():\r\n     y  = rocket_a.ycor() + 10\r\n     if y > 250:\r\n         y = 250\r\n     rocket_a.sety(y)\r\n\r\n\r\ndef move_down():\r\n    y = rocket_a.ycor() - 10\r\n    if y < -250:\r\n        y = -250\r\n    rocket_a.sety(y)\r\n\r\n\r\ndef move_up_b():\r\n    y = rocket_b.ycor() + 10\r\n    if y > 250:\r\n        y = 250\r\n    rocket_b.sety(y)\r\n\r\n\r\ndef move_down_b():\r\n    y = rocket_b.ycor() - 10\r\n    if y < -250:\r\n        y = -250\r\n    rocket_b.sety(y)\r\n\r\nball = turtle.Turtle()\r\nball.shape(\'circle\')\r\nball.speed(0)\r\nball.color(\'red\')\r\nball.dx = 3\r\nball.dy = -3\r\nball.penup()\r\n\r\nwindow.listen()\r\nwindow.onkeypress(move_up, \"w\")\r\nwindow.onkeypress(move_down, \"s\")\r\nwindow.onkeypress(move_up_b, \"Up\")\r\nwindow.onkeypress(move_down_b, \"Down\")\r\n\r\nwhile True:\r\n    window.update()\r\n\r\n    ball.setx(ball.xcor() + ball.dx)\r\n    ball.sety(ball.ycor() + ball.dy)\r\n\r\n    if ball.ycor() >= 290:\r\n        ball.dy = -ball.dy\r\n\r\n    if ball.ycor() <= -290:\r\n        ball.dy = -ball.dy\r\n\r\n    if ball.xcor() >= 490:\r\n        score_b += 1\r\n        s2.clear()\r\n        s2.write(score_b, font=FONT)\r\n        ball.goto(0,randint(-150,150))\r\n        ball.dx = choice([-4,-3,-2, 2,3,4])\r\n        ball.dy = choice([-4,-3,-2, 2,3,4])\r\n\r\n    if ball.xcor() <= -490:\r\n        score_a += 1\r\n        s1.clear()\r\n        s1.write(score_a, font=FONT)\r\n        ball.goto(0,randint(-150,150))\r\n        ball.dx = choice([-4,-3,-2, 2,3,4])\r\n        ball.dy = choice([-4,-3,-2, 2,3,4])\r\n\r\n    if ball.ycor() >= rocket_b.ycor()-50 and ball.ycor() <= rocket_b.ycor()+50 \\\r\n        and ball.xcor() >= rocket_b.xcor()-5 and ball.xcor() <= rocket_b.xcor()+5:\r\n        ball.dx = -ball.dx\r\n\r\n    if ball.ycor() >= rocket_a.ycor()-50 and ball.ycor() <= rocket_a.ycor()+50 \\\r\n        and ball.xcor() >= rocket_a.xcor()-5 and ball.xcor() <= rocket_a.xcor()+5:\r\n        ball.dx = -ball.dx\r\n\r\nwindow.mainloop()</code></pre>','cTV4ML6ksv4',NULL,NULL,'',4);
