INSERT INTO `ege_numbertaskege` VALUES (1,'Системы счисления','ege/photo/ege_1.jpg','Input','ЕГЭ по информатике Задание 1. Тема \"Системы счисления\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 1 информатика','егэ информатика, системы счисления, двоичная, шестнадцатиричная, восьмиричная, значащие нули, количество единиц,ЕГЭ Информатика задание 1'),(2,'Логические функции','ege/photo/ege_2.png','Input','ЕГЭ по информатике Задание 2. Тема \"Логические функции\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 2 информатика','егэ информатика, ЕГЭ Информатика задание 2, импликация, эквивалентность, определите, какому столбцу таблицы соответствует каждая из переменных'),(3,'Анализ информационных моделей','ege/photo/ege_3.png','Input','ЕГЭ по информатике Задание 3. Тема \"Анализ информационных моделей\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 3 информатика','егэ информатика, ЕГЭ Информатика задание 3,На рисунке изображена схема дорог Н-ского района'),(4,'Файловая система и базы данных','ege/photo/ege_4.png','Input','ЕГЭ по информатике Задание 4. Тема \"Файловая система и базы данных\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 4 информатика','егэ информатика, ЕГЭ Информатика задание 4,фрагменте базы данных, маска файла'),(5,'Кодирование и декодирование. Условие Фано','ege/photo/ege_5.jpg','Input','ЕГЭ по информатике Задание 5. Тема \"Кодирование и декодирование. Условие Фано\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 5 информатика','егэ информатика, ЕГЭ Информатика задание 5, условие фано, кодовое слово'),(6,'Выполнение и анализ простых алгоритмов','ege/photo/ege_6.png','Input','ЕГЭ по информатике Задание 6. Тема \"Выполнение и анализ простых алгоритмов\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 6 информатика','егэ информатика, бит чётности, ЕГЭ Информатика задание 6'),(7,'Адресация в электронных таблицах','ege/photo/ege_7.png','Input','ЕГЭ по информатике Задание 7. Тема \"Адресация в электронных таблицах\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 7 информатика','егэ информатика, фрагмент электронной таблицы, диаграмма, значения ячеек,ЕГЭ Информатика задание 7'),(8,'Анализ программ с циклами','ege/photo/ege_8.jpg','Input','ЕГЭ по информатике Задание 8. Тема \"Анализ программ с циклами\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 8 информатика','егэ информатика, ЕГЭ Информатика задание 8'),(9,'Скорость передачи, объем памяти, время передачи','ege/photo/ege_9.jpg','Input','ЕГЭ по информатике Задание 9. Тема \"Скорость передачи, объем памяти, время передачи\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 9 информатика','егэ информатика, объём памяти, разрешение, частота дискретизации, пропускная способность канала, ЕГЭ Информатика задание 9'),(10,'Кодирование, комбинаторика','ege/photo/ege_10.png','Input','ЕГЭ по информатике Задание 10. Тема \"Кодирование, комбинаторика\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 10 информатика','егэ информатика, слова в алфавитном порядке, номер слова, сколько существует слов,ЕГЭ Информатика задание 10'),(11,'Рекурсивные алгоритмы','ege/photo/ege_11.png','Input','ЕГЭ по информатике Задание 11. Тема \"Рекурсивные алгоритмы\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 11 информатика','егэ информатика, рекурсивная процедура, рекурсия, программа, рекурсивная функция,ЕГЭ Информатика задание 11'),(12,'Адресация в сетях TCP/IP','ege/photo/ege_12.jpg','Input','ЕГЭ по информатике Задание 12. Тема \"Адресация в сетях TCP/IP\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 12 информатика','егэ информатика, ip адрес, маска сети, адрес сети, айпи адрес, поразрядная конъюнкция, третий слева байт маски,ЕГЭ Информатика задание 12'),(13,'Вычисление количества информации','ege/photo/ege_13.ico','Input','ЕГЭ по информатике Задание 13. Тема \"Вычисление количества информации\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 13 информатика','егэ информатика, посимвольное кодирование, одинаковым и минимально возможным, дополнительные сведения, объем памяти в байтах,ЕГЭ Информатика задание 13'),(14,'Анализ и выполнение алгоритмов для исполнителя','ege/photo/ege_14.png','Input','ЕГЭ по информатике Задание 14. Тема \"Анализ и выполнение алгоритмов для исполнителя\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 14 информатика','егэ информатика, Чертёжник, алгоритм, Сместиться, Редактор, ЕСЛИ нашлось, заменить,ЕГЭ Информатика задание 14'),(15,'Поиск путей в графе','ege/photo/ege_15.png','Input','ЕГЭ по информатике Задание 15. Тема \"Поиск путей в графе\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 15 информатика','егэ информатика, схема дорог, граф, сколько существует способов добраться,ЕГЭ Информатика задание 15'),(16,'Позиционные системы счисления','ege/photo/ege_16.png','Input','ЕГЭ по информатике Задание 16. Тема \"Позиционные системы счисления\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 16 информатика','егэ информатика, сколько раз встретилась цифра, система счисления,ЕГЭ Информатика задание 16'),(17,'Запросы в поисковых системах','ege/photo/ege_17.png','Input','ЕГЭ по информатике Задание 17. Тема \"Запросы в поисковых системах\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 17 информатика','егэ информатика, запрос, ИЛИ, И, сегмента сети Интернет, все запросы выполнялись одновременно,ЕГЭ Информатика задание 17'),(18,'Логические выражения и множества','ege/photo/ege_18.jpg','Input','ЕГЭ по информатике Задание 18. Тема \"Логические выражения и множества\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 18 информатика','егэ информатика, логическое выражение, укажите длину отрезка, формула тождественно истинна, поразрядную конъюнкцию,ЕГЭ Информатика задание 18'),(19,'Анализ программы по работе с массивом','ege/photo/ege_19.jpg','Input','ЕГЭ по информатике Задание 19. Тема \"Анализ программы по работе с массивом\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 19 информатика','егэ информатика, одномерный массив, значение переменной, фрагмент программы,ЕГЭ Информатика задание 19'),(20,'Анализ программ с циклами','ege/photo/ege_20.png','Input','ЕГЭ по информатике Задание 20. Тема \"Анализ программы по работе с массивом\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 20 информатика','егэ информатика, алгоритм, программа, алгоритм печатает числа,ЕГЭ Информатика задание 20'),(21,'Анализ программ с циклами и подпрограммами','ege/photo/ege_21.png','Input','ЕГЭ по информатике Задание 21. Тема \"Анализ программ с циклами и подпрограммами\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 21 информатика','егэ информатика, алгоритм, программа,ЕГЭ Информатика задание 21'),(22,'Динамическое программирование','ege/photo/ege_22.png','Input','ЕГЭ по информатике Задание 22. Тема \"Динамическое программирование\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 22 информатика','егэ информатика, динамическое программирование, исполнителя есть команды, траектория вычислений,ЕГЭ Информатика задание 22'),(23,'Системы логических уравнений','ege/photo/ege_23.png','Input','ЕГЭ по информатике Задание 23. Тема \"Системы логических уравнений\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 23 информатика','егэ информатика, логические перемененные, различные наборы значений, система уравнений,ЕГЭ Информатика задание 23'),(24,'Исправление фрагмента программы и ошибок','ege/photo/24.png','NoInp','ЕГЭ по информатике Задание 24. Тема \"Исправление фрагмента программы и ошибок\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 24 информатика','егэ информатика,ЕГЭ Информатика задание 24'),(25,'Программа на обработку массива','ege/photo/array.png','NoInp','ЕГЭ по информатике Задание 25. Тема \"Программа на обработку массива\". Задачи ЕГЭ информатика. Тест ЕГЭ задание 25 информатика','егэ информатика, массивы, массив, опишите на одном из языков программирования алгоритм,ЕГЭ Информатика задание 25');
