INSERT INTO `ege_questionsege` VALUES (10,'В фрагменте базы данных представлены сведения о родственных отношениях. Определите на основании приведенных данных, сколько родных сестер есть у Лесных П.А.','','ID	Фамилия И.О.	Пол\r\n2011	Ковач Л.П.	Ж\r\n2012	Данзас К.К.	М\r\n2024	Павлова В.А.	Ж\r\n2045	Лесных Л.А.	Ж\r\n2056	Данзас Е.Ф.	Ж\r\n2077	Ларина Т.Д.	Ж\r\n2083	Данзас И.К.	М\r\n2094	Данзас Е.К.	Ж\r\n2115	Лесных А.П.	М\r\n2140	Данзас Т.И.	Ж\r\n2162	Данзас П.И.	М\r\n2171	Гиппиус З.А.	Ж\r\n2186	Молчалина С.А.	Ж\r\n2201	Лесных П.А.	М\r\n#####\r\nID_Родителя	ID_Ребенка\r\n2094	2045\r\n2115	2045\r\n2011	2083\r\n2012	2083\r\n2011	2094\r\n2012	2094\r\n2056	2140\r\n2083	2140\r\n2056	2162\r\n2083	2162\r\n2094	2186\r\n2115	2186\r\n2094	2201\r\n2115	2201','','','',809,37,'2121',12,4,11,NULL),(15,'Сколько единиц в двоичной записи шестнадцатеричного числа BC1<sub>16</sub>?','','','','','',49,120,'6',2,1,12,NULL),(16,'Сколько единиц в двоичной записи шестнадцатеричного числа 2C4<sub>16</sub>?','','','','','',21,122,'4',2,1,11,14),(17,'Сколько единиц в двоичной записи шестнадцатеричного числа BD09<sub>16</sub>?','','','','','',33,102,'8',2,1,NULL,NULL),(18,'Сколько значащих нулей в двоичной записи шестнадцатеричного числа 4A67<sub>16</sub>?','','','','','',72,102,'7',2,1,10,NULL),(19,'Сколько значащих нулей в двоичной записи шестнадцатеричного числа 3BC<sub>16</sub>?','','','','','',17,108,'3',2,1,9,NULL),(20,'Сколько значащих нулей в двоичной записи шестнадцатеричного числа 46E0<sub>16</sub>?','','','','','',19,111,'9',2,1,NULL,15),(21,'Сколько значащих нулей в двоичной записи шестнадцатеричного числа 47F0C1<sub>16</sub>?','','','','','',60,106,'12',2,1,8,NULL),(22,'Сколько значащих разрядов в двоичной записи шестнадцатеричного числа 3FD02C<sub>16</sub>?','','','','','',37,99,'22',2,1,NULL,NULL),(23,'Сколько значащих разрядов в двоичной записи шестнадцатеричного числа 54BF2<sub>16</sub>?','','','','','',69,111,'19',2,1,7,NULL),(25,'Сколько единиц в двоичной записи числа 345?','',