А.	Ж\r\n2201	Куинджи П.А.	М\r\n#####\r\nID_Родителя	ID_Ребенка\r\n2011	2083\r\n2011	2094\r\n2012	2083\r\n2012	2094\r\n2024	2115\r\n2056	2140\r\n2056	2162\r\n2083	2140\r\n2083	2162\r\n2094	2186\r\n2094	2201\r\n2115	2186\r\n2115	2201','','','',104,148,'4',12,4,NULL,NULL),(100,'Ниже на трех языках программирования записан алгоритм. Получив на вход число x, этот алгоритм печатает два числа: L и M. Укажите наименьшее число x, при вводе которого алгоритм печатает сначала 4, а потом 7.','','','x = int(input())\r\nL = 0\r\nM = 0\r\nwhile x > 0:\r\n   M = M + 1\r\n   if x % 2 != 0:\r\n      L = L + 1\r\n   x = x // 2\r\nprint(L)\r\nprint(M)','var x, L, M: integer;\r\nbegin\r\n  readln(x);\r\n  L := 0;\r\n  M := 0;\r\n  while x > 0 do begin\r\n    M := M + 1;\r\n    if x mod 2 <> 0 then\r\n      L := L + 1;\r\n    x := x div 2;\r\n  end;\r\n  writeln(L);\r\n  writeln(M);\r\nend.','#include <iostream>\r\nusing namespace std;\r\nvoid main()\r\n{\r\n	int x, L, M;\r\n	cin >> x;\r\n	L = 0;\r\n	M = 0;\r\n	while (x > 0) {\r\n		M = M + 1;\r\n		if (x % 2 != 0) {\r\n			L = L + 1;\r\n		}\r\n		x = x / 2;\r\n	}\r\n	cout << L;\r\n	cout << M;\r\n}',48,45,'71',41,20,10,NULL),(101,'Ниже на трех языках программирования записан алгоритм. Получив на вход число x, эта программа печатает два числа a и b. Укажите наименьшее пятизначное число x, при вводе которых алгоритм печатает сначала 5, а потом 3.','','','x = int(input())\r\na = 0\r\nb = 0\r\nwhile x > 0:\r\n    y = x % 10\r\n    if y > 4: \r\n       a = a + 1\r\n    if y < 6: \r\n       b = b + 1\r\n    x = x // 10\r\nprint(a)\r\nprint(b)','var x, y, a, b: longint;\r\nbegin\r\n  a := 0;\r\n  b := 0;\r\n  readln(x);\r\n  while x > 0 do begin\r\n    y := x mod 10;\r\n    if y > 4 then a := a + 1;\r\n    if y < 6 then b := b + 1;\r\n    x := x div 10;\r\n  end;\r\n  writeln(a);\r\n  writeln(b);\r\nend.','#include <iostream>\r\nusing namespace std;\r\nvoid main()\r\n{\r\n	int x, y, a, b;\r\n	a = 0;\r\n	b = 0;\r\n	cin >> x;\r\n	while (x > 0) {\r\n		y = x % 10;\r\n		if (y > 4) a = a + 1;\r\n		if (y < 6) b = b + 1;\r\n		x = x / 10;\r\n	}\r\n	cout << a;\r\n	cout << b;\r\n}',36,29,'55566',41,20,NULL,NULL),(102,'Ниже на трех языках программирования записан алгоритм. Получив на вход число x, эта программа печатает два числа a и b. Укажите наименьшее из таких чисел x, при вводе которых алгоритм печатает сначала 2, а потом 3, при условии, что число должно состоять из цифр, больших 5','','','x = int(input())\r\na = 0 \r\nb = 0\r\nwhile x > 0: \r\n   c =  x % 2\r\n   if c == 0: \r\n      a =  a + 1\r\n   else:\r\n      b =  b + 1\r\n   x =  x // 10  \r\nprint(a)\r\nprint(b)','var x, a, b, c: integer;\r\nbegin\r\n  readln(x);\r\n  a := 0; \r\n  b := 0;\r\n  while x > 0 do begin\r\n    c := x mod 2;\r\n    if c = 0 then a := a + 1\r\n    else b := b + 1;\r\n    x := x div 10;\r\n  end;\r\n  writeln(a); write(b);\r\nend.','#include <iostream>\r\nusing namespace std;\r\nvoid main()\r\n{\r\n	int x, a, b, c;\r\n	cin >> x;\r\n	a = 0;\r\n	b = 0;\r\n	while (x > 0) {\r\n		c = x % 2;\r\n		if (c == 0) a = a + 1;\r\n		else b = b + 1;\r\n		x = x / 10;\r\n	}\r\n	cout << a;\r\n	cout<<b;\r\n}',27,26,'66777',41,20,9,NULL),(103,'Ниже на трех языках программирования записан алгоритм. Получив на вход число x, эта программа печатает два числа a и b. Укажите наименьшее из чисел x, при вводе которых алгоритм печатает сначала 14, а потом 6.','','','x = int(input())\r\na = 0\r\nb = 10\r\nwhile x > 0:\r\n   c = x % 10\r\n   a = a + c\r\n   if c < b:\r\n      b = c\r\n   x = x // 10\r\nprint(a)\r\nprint(b)','var x, a, b, c: integer;\r\nbegin\r\n  readln(x);\r\n  a := 0; \r\n  b := 10;\r\n  while x > 0 do begin\r\n    c := x mod 10;\r\n    a := a + c;\r\n    if c < b then b := c;\r\n    x := x div 10;\r\n  end;\r\n  writeln(a); write(b);\r\nend.','#include <iostream>\r\nusing namespace std;\r\nvoid main()\r\n{\r\n	int x, a, b, c;\r\n	cin >> x;\r\n	a = 0;\r\n	b = 10;\r\n	while (x > 0) {\r\n		c = x % 10;\r\n		a = a + c;\r\n		if (c == b) b = c;\r\n		