ло x, эта программа печатает два числа a и b. Укажите наименьшее из таких чисел x, при вводе которых алгоритм печатает сначала 4, а потом 13.','','','x = int(input())\r\na = 0\r\nb = 0\r\nwhile x > 0:\r\n   a = a + 1\r\n   b = b + (x % 7)\r\n   x = x // 7\r\nprint(a)\r\nprint(b)','var x, a, b: integer;\r\nbegin\r\n  readln(x);\r\n  a := 0; \r\n  b := 0;\r\n  while x > 0 do begin\r\n    a := a + 1;\r\n    b := b + (x mod 7);\r\n    x := x div 7;\r\n  end;\r\n  writeln(a); write(b);\r\nend.','#include <iostream>\r\nusing namespace std;\r\nvoid main()\r\n{\r\n	int x, a, b;\r\n	cin >> x;\r\n	a = 0;\r\n	b = 0;\r\n	while (x > 0) {\r\n		a = a + 1;\r\n		b = b + (x % 7);\r\n		x = x / 7;\r\n	}\r\n	cout << a;\r\n	cout << b;\r\n}',75,33,'391',41,20,7,NULL),(107,'Ниже на трех языках программирования записан алгоритм. Получив на вход число x, эта программа печатает два числа a и b. Укажите наименьшее из таких чисел x, при вводе которых алгоритм печатает сначала 4, а потом 2.','','','x = int(input())\r\na = 0 \r\nb = 0\r\nwhile x > 0: \r\n   c =  x % 2\r\n   if c == 0: \r\n      a =  a + 1\r\n   else:\r\n      b =  b + 1\r\n   x =  x // 10  \r\nprint(a)\r\nprint(b)','var x, a, b, c: integer;\r\nbegin\r\n  readln(x);\r\n  a := 0; \r\n  b := 0;\r\n  while x > 0 do begin\r\n    c := x mod 2;\r\n    if c = 0 then a := a + 1\r\n    else b := b + 1;\r\n    x := x div 10;\r\n  end;\r\n  writeln(a); write(b);\r\nend.','#include <iostream>\r\nusing namespace std;\r\nvoid main()\r\n{\r\n	int x, a, b, c;\r\n	cin >> x;\r\n	a = 0;\r\n	b = 0;\r\n	while (x > 0) {\r\n		c = x % 2;\r\n		if (c == 0) a = a + 1;\r\n		else b = b + 1;\r\n		x = x / 10;\r\n	}\r\n	cout << a;\r\n	cout << b;\r\n}',65,55,'100001',41,20,12,NULL),(108,'Ниже на трех языках программирования записан алгоритм. Получив на вход число х, этот алгоритм печатает два числа a и b. Укажите наибольшее из таких чисел х, при вводе которых алгоритм печатает сначала подумать 2, а потом 150.','','','x = int(input())\r\na = 0\r\nb = 0\r\nwhile x > 0:\r\n  a = a + 1\r\n  b = b + (x % 100)\r\n  x = x // 100\r\nprint(a)\r\nprint(b)','var x, a, b: integer;\r\nbegin\r\n  readln(x);\r\n  a := 0; \r\n  b := 0;\r\n  while x > 0 do begin\r\n    a := a + 1;\r\n    b := b + (x mod 100);\r\n    x := x div 100;\r\n  end;\r\n  writeln(a); write(b);\r\nend.','#include <iostream>\r\nusing namespace std;\r\nvoid main()\r\n{\r\n	int x, a, b;\r\n	cin >> x;\r\n	a = 0;\r\n	b = 0;\r\n	while (x > 0) {\r\n		a = a + 1;\r\n		b = b + (x % 100);\r\n		x = x / 100;\r\n	}\r\n	cout << a;\r\n	cout << b;\r\n}',24,45,'9951',41,20,6,NULL),(109,'Ниже на трех языках программирования записан алгоритм. Получив на вход число x, этот алгоритм печатает число M. Известно, что x > 100. Укажите наименьшее такое (т.е. большее 100) число x, при вводе которого алгоритм печатает 26.','','','x = int(input())\r\nL = x\r\nM = 65\r\nif L % 2 == 0:\r\n  M = 52\r\nwhile L != M:\r\n  if L > M:\r\n     L = L - M\r\n  else:\r\n     M = M - L\r\nprint(M)','var x, L, M: integer;\r\nbegin\r\n  readln(x);\r\n  L := x;\r\n  M := 65;\r\n  if L mod 2 = 0 then\r\n    M := 52;\r\n  while L <> M do\r\n    if L > M then\r\n      L := L - M\r\n    else\r\n      M := M – L;\r\n  writeln(M);\r\nend.','#include <iostream>\r\nusing namespace std;\r\nvoid main()\r\n{\r\n	int x, L, M;\r\n	cin >> x;\r\n	L = x;\r\n	M = 65;\r\n	if (L % 2 == 0) M = 52;\r\n	while (L != M) {\r\n		if (L > M) L = L - M;\r\n		else M = M - L;\r\n	}\r\n	cout << M;\r\n}',290,65,'130',42,20,NULL,45),(110,'Ниже на трех языках программирования записан алгоритм. Получив на вход число x, эта программа печатает два числа a и b. Укажите наименьшее пятизначное число x, при вводе которых алгоритм печатает сначала 2, а потом 4.','','','x = int(input())\r\na = 0\r\nb = 0\r\nwhile x > 0:\r\n    y = x % 10\r\n    if y > 3: \r\n       a = a + 1\r\n    if y < 7: \r\n       b = b + 1\r\n    x = x // 10\r\nprint(a)\r\nprint(b)','var x, y, a, b: longint;\r\nbegin\r\n  a := 0;\r\n  b := 0;\r\n  readln(x);\r\n  while x > 0 do begin\r\n    y := x mod 10;\r\n    if y > 3 then a := a + 1;\r\n    if y < 7 then b := b + 1;\r\n    x := x div 10;\r\n  end;\r\n  writeln(a);\r\n  writeln(b);\r\nend.','#include <iostream>\r\nusing namespace std;\r\nvoid main()\r\n{\r\n	int x, y, a, b;\r\n	a = 0;\r\n	b = 0;\r\n	cin >> x;\r\n	while (x > 0) {\r\n		y = x % 10;\r\n		if (y > 3) a = a + 1;\r\n		if (y < 7) b = b + 1;\r\n		x = x / 10;\r\n	}\r\n	cout << a;\r\n	cout << b;\r\n}',116,44,'10047',41,20,5,54),(111,'Ниже на трех языках программирования записан алгоритм. Получив на вход число x, этот алгоритм печатает число M. Известно, что х > 40. Укажите наименьшее такое (т.е. большее 40) число х, при вводе которого алгоритм печатает 2.','','','x = int(input())\r\nL = x\r\nM = 12\r\nif L % 2 == 0:\r\n    M = 24\r\nwhile L != M:\r\n    if L > M:\r\n        L = L - M\r\n    else:\r\n        M = M - L\r\nprint(M)','var x, L, M: integer;\r\nbegin\r\n    readln(x);\r\n    L : = x;\r\n    M := 12;\r\n    if L mod 2 = 0 then\r\n        M := 24;\r\n    while L <> M do\r\n        if L > M then\r\n            L := L - M\r\n        else\r\n            M := M - L;\r\n    writeln(M);\r\nend.','#include <iostream>\r\nusing namespace std;\r\nvoid main()\r\n{\r\n	int x, L, M;\r\n	cin >> x;\r\n	L = x;\r\n	M = 12;\r\n	if (L % 2 == 0) M = 24;\r\n	while (L != M) {\r\n		if (L > M) L = L - M;\r\n		else M = M - L;\r\n	}\r\n	cout << M;\r\n}',63,46,'46',42,20,4,NULL),(112,'Ниже на трех языках программирования записан алгоритм. Получив на вход число x, эта программа печатает два числа a и b. Укажите наибольшее из таких чисел x, при вводе которых алгоритм печатает сначала 3, а потом 24.','','','x = int(input())\r\na = 0\r\nb = 1\r\nwhile x > 0:\r\n   a = a + 1\r\n   b = b * (x % 5)\r\n   x = x // 5\r\nprint(a)\r\nprint(b)','var x, a, b: integer;\r\nbegin\r\n  readln(x);\r\n  a := 0; \r\n  b := 1;\r\n  while x > 0 do begin\r\n    a := a + 1;\r\n    b := b * (x mod 5);\r\n    x := x div 5;\r\n  end;\r\n  writeln(a); write(b);\r\nend.','#include 