ользуется одномерный целочисленный массив А с индексами от 0 до 9. Значения элементов равны 5, 6, 5, 8, 5, 4, 1, 2, 9, 6 соответственно, т.е. А[0] = 5, А[1] = 6 и т.д.\r\nОпределите значение переменной с после выполнения следующего фрагмента этой программы (записанного ниже на трех языках программирования).','','','c = 0\r\nfor i in range(9):\r\n   if A[i] >= A[9]:\r\n       c = c + 1\r\n       t = A[i]\r\n       A[i] = A[9]\r\n       A[9] = t','c := 0;\r\nfor i := 0 to 8 do\r\n  if A[i] >= A[9] then\r\n  begin\r\n    c := c + 1;\r\n    t := A[i];\r\n    A[i] := A[9];\r\n    A[9] := t;\r\n  end;','c = 0;\r\nfor (i = 0; i < 9; i++) {\r\n	if (A[i] >= A[9]) {\r\n		c = c + 1;\r\n		t = A[i];\r\n		A[i] = A[9];\r\n		A[9] = t;\r\n	}\r\n}',12,8,'3',39,19,11,NULL),(116,'В программе описан одномерный целочисленный массив с индексами от 0 до 10. Ниже представлен фрагмент программы, записанный на трех языках программирования.\r\n---\r\nВ начале выполнения этого фрагмента в массиве находились двухзначные нечётные натуральные числа. Какое наибольшее значение может иметь переменная s после выполнения данной программы?','','','s = 0\r\nn = 10\r\nfor i in range(n):\r\n   s = s+2*A[i]+A[i+1]','s := 0;\r\nn := 10;\r\nfor i := 0 to n-1 do\r\n  s := s+2*A[i]+A[i+1];','s = 0;\r\nn = 10;\r\nfor (i = 0; i < n; i++) {\r\n	s = s+2*A[i]+A[i + 1];\r\n}',42,8,'2970',40,19,NULL,NULL),(117,'В программе используется одномерный целочисленный массив A с индексами от 0 до 9. Значения элементов равны 8, 7, 6, 6, 6, 5, 3, 3, 2, 1 соответственно, т.е. A[0] = 8, A[1] = 7 и т.д.\r\nОпределите значение переменной c после выполнения следующего фрагмента этой программы (записанного ниже на трех языках программирования).','','','c = 0\r\nfor i in range(1,10):\r\n   if A[i] < A[0]:\r\n      c = c + 1\r\n      t = A[i]\r\n      A[i] = A[0]\r\n      A[0] = t','c := 0;\r\nfor i := 1 to 9 do\r\n  if A[i] < A[0] then\r\n  begin\r\n    c := c + 1;\r\n    t := A[i];\r\n    A[i] := A[0];\r\n    A[0] := t;\r\n  end;','c = 0;\r\nfor (i = 0; i < 9; i++) {\r\n	if (A[i] < A[0]) {\r\n		c = c + 1;\r\n		t = A[i];\r\n		A[i] = A[0];\r\n		A[0] = t;\r\n	}\r\n}',16,11,'6',39,19,10,NULL),(118,'В программе описан одномерный целочисленный массив с индексами от 0 до 10. Ниже представлен фрагмент программы, записанный на трех языках программирования.\r\n---\r\nВ начале выполнения этого фрагмента в массиве находились двухзначные чётные натуральные числа. Какое наибольшее значение может иметь переменная s после выполнения данной программы?','','','s = 0\r\nn = 10\r\nfor i in range(n):\r\n   s = s + A[i] + A[i+1]','s := 0;\r\nn := 10;\r\nfor i := 0 to n-1 do\r\n  s := s + A[i] + A[i+1];','s = 0;\r\nn = 10;\r\nfor (i = 0; i < n; i++) {\r\n	s = s + A[i] + A[i + 1];\r\n}',74,10,'1960',40,19,NULL,NULL),(119,'В программе описан одномерный целочисленный массив с индексами от 0 до 10. Ниже представлен фрагмент программы, записанный на трех языках программирования.\r\n---\r\nИзвестно, что в начале выполнения этого фрагмента в массиве находилась возрастающая последовательность натуральных чисел, то есть A[0] < A[1] < … < A[10]. Какое наибольшее значение может иметь переменная s после выполнения данной программы?','','','s = 27\r\nn = 10\r\nfor i in range(n):\r\n    s = s+A[i]-A[i+1]+2','s := 27;\r\nn := 10;\r\nfor i := 0 to n-1 do\r\n  s := s+A[i]-A[i+1]+2;','s = 27;\r\nn = 10;\r\nfor (i = 0; i < n; i++) {\r\n   s = s +A[i]-A[i + 1]+ 2;\r\n}',111,38,'37',40,19,9,NULL),(120,'В программе используется одномерный целочисленный массив A с индексами от 0 до 9. Значения элементов равны 8, 4, 3, 0, 7, 2, 1, 5, 9, 6 соответственно, т.е. A[0] = 8, A[1] = 4 и т.д.\r\nОпределите значение переменной s после выполнения следующего фрагмента этой программы (записанного ниже на трех языках программирования).','','','s = 0\r\nfor j in range(9):\r\n   if A[j] > A[j+1]:\r\n      s = s + 1\r\n      t = A[j]\r\n      A[j] = A[j+1]\r\n      A[j+1] = t','s := 0;\r\nfor j := 0 to 8 do\r\n  if A[j] > A[j+1] then\r\n  begin\r\n    s := s + 1;\r\n    t := A[j];\r\n    A[j] := A[j+1];\r\n    A[j+1] := t;\r\n  end;','s = 0;\r\nfor (j = 0; i < 9; i++) {\r\n	if (A[j] > A[j+1]) {\r\n		s = s + 1;\r\n		t = A[j];\r\n		A[j] = a[j+1];\r\n		A[j+1] = t;\r\n	}\r\n}',21,14,'8',39,19,NULL,NULL),(121,'В программе используется одномерный целочисленный массив A с индексами от 0 до 9. Значения элементов равны 4, 7, 9, 8, 4, 8, 1, 2, 9, 6 соответственно, т.е. A[0] = 4, A[1] = 7 и т.д.\r\nОпределите значение переменной с после выполнения следующего фрагмента этой программы (записанного ниже на трех языках программирования).','','','c = 0\r\nfor i in range(1,10):\r\n   if A[i] > A[0]:\r\n       c = c + 1\r\n       t = A[i]\r\n       A[i] = A[0]\r\n       A[0] = t','c := 0;\r\nfor i := 1 to 9 do\r\n  if A[i] > A[0] then\r\n  begin\r\n    c := c + 1;\r\n    t := A[i];\r\n    A[i] := A[0];\r\n    A[0] := t;\r\n  end;','c = 0;\r\nfor (i = 1; i < 9; i++) {\r\n	if (A[i] >= A[0]) {\r\n		c = c + 1;\r\n		t = A[i];\r\n		A[i] = a[0];\r\n		A[0] = t;\r\n	}\r\n}',7,11,'2',39,19,8,NULL),(122,'В программе описан одномерный целочисленный массив с индексами от 0 до 10. Ниже представлен фрагмент программы, записанный на трех языках программирования.\r\n---\r\nИзвестно, что в начале выполнения этого фрагмента в массиве находилась убывающая последовательность натуральных чисел, то есть A[0] > A[1] >…> A[10]. Какое наименьшее значение может иметь переменная s после выполнения данной программы?','','','s = 15\r\nn = 10\r\nfor i in range(n):\r\n    s = s+A[i]-A[i+1]','s := 15;\r\nn := 10;\r\nfor i := 0 to n-1 do\r\n   s := s+A[i]-A[i+1];','s = 15;\r\nn = 10;\r\nfor (i = 0; i < n; i++) {\r\n	s = s + A[i] - A[i + 1];\r\n}',53,13,'25',40,19,NULL,NULL),(123,'В программе используется одномерный целочисленный массив A с индексами от 0 до 9. Значения элементов равны 3, 5, 1, 7, 3, 6, 8, 5, 9, 4 соответственно, т.е. A[0] = 3, A[1] = 5 и т.д.\r\nОпределите значение переменной s после выполнения следующего фрагмента этой программы (записанного ниже на 