INSERT INTO `oge_numbertaskoge` VALUES (1,'Количество информации в тексте','oge/photo/oge_1.png','Radio','ОГЭ по информатике Задание 1. Тема \"Количество информации в тексте\". Задачи ОГЭ информатика. Тест ОГЭ задание 1 информатика','ОГЭ информатика, бит, байт, кбайт, объём памяти,информационный объем,тест огэ информатика задание 1,определите информационный объём статьи'),(2,'Логические выражения','oge/photo/oge_2.png','Radio','ОГЭ по информатике Задание 2 Тема \"Логические выражения\". Задачи ОГЭ информатика. Тест ОГЭ задание 2 информатика','ОГЭ информатика, ИЛИ, И, НЕ, дизъюнкция, конъюнкция, инверсия, истинно, ложно,тест огэ информатика задание 2,ложно выражение,истинно выражение'),(3,'Кратчайший путь в графе','oge/photo/oge_3.png','Radio','ОГЭ по информатике Задание 3 Тема  \"Кратчайший путь в графе\". Задачи ОГЭ информатика. Тест ОГЭ задание 3 информатика','ОГЭ информатика, длину кратчайшего пути,тест огэ информатика задание 3,между населёнными пунктами a b c d e f построены дороги,определите длину кратчайшего пути'),(4,'Файловая система','oge/photo/oge_4.jpg','Radio','ОГЭ по информатике Задание 4 Тема  \"Файловая система\". Задачи ОГЭ информатика. Тест ОГЭ задание 4 информатика','ОГЭ информатика, каталог, полный путь, полное имя файла,тест огэ информатика задание 4,возможный полный путь каталога,каким было полное имя этого файла до перем'),(5,'Диаграммы в электронных таблицах','oge/photo/oge_5.jpg','Radio','ОГЭ по информатике Задание 5 Тема  \"Диаграммы в электронных таблицах\". Задачи ОГЭ информатика. Тест ОГЭ задание 5 информатика','ОГЭ информатика, диапазона ячеек,тест огэ информатика задание 5,дан фрагмент электронной таблицы,дан фрагмент электронной таблицы в первой строке'),(6,'Выполнение алгоритмов для исполнителей','oge/photo/oge_6.jpg','Radio','ОГЭ по информатике Задание 6 Тема  \"Выполнение алгоритмов для исполнителей\". Задачи ОГЭ информатика. Тест ОГЭ задание 6 информатика','ОГЭ информатика, Чертёжник, Черепашка,тест огэ информатика задание 6,чертёжнику был дан для исполнения следующий алгоритм,Черепашке был дан для исполнения'),(7,'Кодирование и декодирование сообщений','oge/photo/oge_7.jpg','Input','ОГЭ по информатике Задание 7 Тема  \"Кодирование и декодирование сообщений\". Задачи ОГЭ информатика. Тест ОГЭ задание 7 информатика','ОГЭ информатика, кодовая таблица, расшифрованное слово,тест огэ информатика задание 7,мальчики играли в шпионов и закодировали,валя шифрует русские слова'),(8,'Оператор присваивания','oge/photo/oge_8.jpg','Input','ОГЭ по информатике Задание 8 Тема  \"Оператор присваивания\". Задачи ОГЭ информатика. Тест ОГЭ задание 8 информатика','ОГЭ информатика, фрагмент программы, переменная,тест огэ информатика задание 8,определите значение переменной после выполнения следующего фрагмента'),(9,'Программы с циклами','oge/photo/oge_9.jpg','Input','ОГЭ по информатике Задание 9 Тема  \"Программы с циклами\". Задачи ОГЭ информатика. Тест ОГЭ задание 9 информатика','ОГЭ информатика, переменная, программа,тест огэ информатика задание 9,запишите значение переменной полученное в результате работы следующей программы'),(10,'Обработка массивов','oge/photo/oge_10.png','Input','ОГЭ по информатике Задание 10 Тема  \"Обработка массивов\". Задачи ОГЭ информатика. Тест ОГЭ задание 10 информатика','ОГЭ информатика, одномерный массив,тест огэ информатика задание 10,в программе используется одномерный целочисленный массив'),(11,'Количество путей в графе','oge/photo/oge_11.png','Input','ОГЭ по информатике Задание 11 Тема  \"Количество путей в графе\". Задачи ОГЭ информатика. Тест ОГЭ задание 11 информатика','ОГЭ информатика, схема дорог, способов добраться,тест огэ информатика задание 11,на рисунке представлена схема дорог, связывающих города'),(12,'Базы данных. Проверка условия','oge/photo/oge_12.jpg','Input','ОГЭ по информатике Задание 12 Тема  \"Базы данных. Проверка условия\". Задачи ОГЭ информатика. Тест ОГЭ задание 12 информатика','ОГЭ информатика, фрагмент базы данных, записей удовлетворяют,тест огэ информатика задание 12,ниже в табличной форме представлен фрагмент базы данных'),(13,'Двоичная система счисления','oge/photo/oge_13.png','Input','ОГЭ по информатике Задание 13 Тема  \"Двоичная система счисления\". Задачи ОГЭ информатика. Тест ОГЭ задание 13 информатика','ОГЭ информатика, двоичная система, десятичная система,тест огэ информатика задание 13,переведите число из десятичной системы счисления в двоичную'),(14,'Составление программ для исполнителя','oge/photo/oge_14.jpg','Input','ОГЭ по информатике Задание 14 Тема  \"Составление программ для исполнителя\". Задачи ОГЭ информатика. Тест ОГЭ задание 14 информатика','ОГЭ информатика, порядок команд,тест огэ информатика задание 14,запишите порядок команд в программе которая преобразует число'),(15,'Скорость передачи данных','oge/photo/oge_15.png','Input','ОГЭ по информатике Задание 15 Тема  \"Скорость передачи данных\". Задачи ОГЭ информатика. Тест ОГЭ задание 15 информатика','ОГЭ информатика, размер файла, байт, кбайт, бит, скорость соединения,тест огэ информатика задание 15,файл размером передаётся через некоторое соединение'),(16,'Выполнение и анализ алгоритма для автомата','oge/photo/oge_16.png','Input','ОГЭ по информатике Задание 16 Тема  \"Выполнение и анализ алгоритма для автомата\". Задачи ОГЭ информатика. Тест ОГЭ задание 16 информатика','ОГЭ информатика, автомат получает числа,тест огэ информатика задание 16,автомат получает на вход два,некоторый алгоритм из одной цепочки символов получает новую'),(17,'Составление адреса URL из частей','oge/photo/oge_17.jpg','Input','ОГЭ по информатике Задание 17 Тема  \"Составление адреса URL из частей\". Задачи ОГЭ информатика. Тест ОГЭ задание 17 информатика','ОГЭ информатика, адрес файла, сервер, протокол,тест огэ информатика задание 17,доступ к файлу находящемуся на сервере,находящемуся на сервере осуществляется по'),(18,'Поисковые запросы в Интернете','oge/photo/oge_18.png','Input','ОГЭ по информатике Задание 18 Тема  \"Поисковые запросы в Интернете\". Задачи ОГЭ информатика. Тест ОГЭ задание 18 информатика','ОГЭ информатика, ИЛИ, И, запрос,тест огэ информатика задание 18,Расположите коды запросов в порядке возрастания количества страниц,В языке запросов поискового'),(19,'Обработка данных в Excel','oge/photo/42ed64b88d07.jpg','NoInp','ОГЭ по информатике Задание 19. Тема \"Обработка данных в Excel\". Задачи ОГЭ информатика. Тест ОГЭ задание 19 информатика','Excel ОГЭ информатика, Электронная таблица, ОГЭ информатика 19,информатика задание 19'),(21,'Написание программы','oge/photo/programmyi-dlya-zagruzki-filmov.png','NoInp','ОГЭ по информатике Задание 21. Тема \"Написание программы\". Задачи ОГЭ информатика. Тест ОГЭ задание 21 информатика','программа, 20.2 информатика огэ, огэ написать программу');
