DROP TABLE IF EXISTS `oge_questionsoge`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `oge_questionsoge` (
  `id` int NOT NULL AUTO_INCREMENT,
  `text` longtext NOT NULL,
  `picture` varchar(100) NOT NULL,
  `table_data` longtext,
  `code_python` longtext,
  `code_pascal` longtext,
  `code_c_plus` longtext,
  `var_of_choice_answer` longtext,
  `file` varchar(100) DEFAULT NULL,
  `failed` int NOT NULL,
  `passed` int NOT NULL,
  `answer` varchar(30) NOT NULL,
  `category_id` int DEFAULT NULL,
  `number_of_task_id` int NOT NULL,
  `number_of_variant_id` int DEFAULT NULL,
  `q_url_video_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `q_url_video_id` (`q_url_video_id`),
  KEY `oge_questionsoge_category_id_03e68227_fk_oge_categoryoge_id` (`category_id`),
  KEY `oge_questionsoge_number_of_task_id_f5846c5d_fk_oge_numbe` (`number_of_task_id`),
  KEY `oge_questionsoge_number_of_variant_id_d56109e6_fk_oge_varia` (`number_of_variant_id`),
  CONSTRAINT `oge_questionsoge_category_id_03e68227_fk_oge_categoryoge_id` FOREIGN KEY (`category_id`) REFERENCES `oge_categoryoge` (`id`),
  CONSTRAINT `oge_questionsoge_number_of_task_id_f5846c5d_fk_oge_numbe` FOREIGN KEY (`number_of_task_id`) REFERENCES `oge_numbertaskoge` (`number`),
  CONSTRAINT `oge_questionsoge_number_of_variant_id_d56109e6_fk_oge_varia` FOREIGN KEY (`number_of_variant_id`) REFERENCES `oge_variantoge` (`id`),
  CONSTRAINT `oge_questionsoge_q_url_video_id_8bd4beb6_fk_oge_video` FOREIGN KEY (`q_url_video_id`) REFERENCES `oge_videorazboroge` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=315 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

