CREATE TABLE `videos_course` (
  `id` int NOT NULL AUTO_INCREMENT,
  `language` varchar(3) NOT NULL,
  `theme` varchar(100) NOT NULL,
  `article` longtext,
  `number_theme` int DEFAULT NULL,
  `youtube_id` varchar(75) DEFAULT NULL,
  `seo_keywords` longtext NOT NULL,
  `slug` varchar(50) DEFAULT NULL,
  `stepic` varchar(100) DEFAULT NULL,
  `is_closed_video` tinyint(1) NOT NULL,
  `patreon` varchar(200) NOT NULL,
  `boosty` varchar(200) NOT NULL,
  `rutube_id` varchar(75) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `videos_course_slug_30a94ba5_uniq` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=271 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
