INSERT INTO `videos_programmtask` VALUES (1,'Арифметика','http://acmp.ru/asp/do/index.asp?main=task&id_course=1&id_section=2&id_topic=29&id_problem=163','',10,NULL,'',''),(2,'Счастливый билет','http://acmp.ru/asp/do/index.asp?main=task&id_course=1&id_section=2&id_topic=29&id_problem=164','',20,'d3sDE8tNBc8','https://www.patreon.com/posts/schastlivyi-35039588',''),(4,'Максимум из двух чисел','https://informatics.msk.ru/mod/statements/view.php?id=276','',8,NULL,'',''),(5,'Какое из чисел больше?','https://informatics.msk.ru/mod/statements/view3.php?id=276&chapterid=293','',5,NULL,'',''),(6,'Ладья','http://acmp.ru/asp/do/index.asp?main=topic&id_course=1&id_section=2&id_topic=30','',12,NULL,'',''),(7,'Слон','http://acmp.ru/asp/do/index.asp?main=task&id_course=1&id_section=2&id_topic=30&id_problem=185','',15,NULL,'',''),(8,'77 лет','','<p>Напишите программу, которая запрашивает имя пользователя и его возраст. Программа должна вывести на экран сообщение, содержащее имя пользователя и год, когда ему исполниться 77 лет.</p>',14,'YzSYIbp_OXI','https://www.patreon.com/posts/reshenie-zadachi-43652038',''),(10,'Налог 13%','','Как вы знаете, в нашей стране граждане платят подоходный налог 13%. \r\nПредставьте, что люди с доходом меньше 20000 рублей освобождены от уплаты налога.\r\nНапишите программу, которая получает на вход значение дохода и выводит на экран сумму, оставшуюся после уплаты налога в 13%.',5,NULL,'',''),(11,'Шоколадка','https://informatics.msk.ru/mod/statements/view3.php?id=276&chapterid=258#1','',17,NULL,'',''),(12,'Существует ли треугольник?','https://informatics.msk.ru/mod/statements/view3.php?id=276&chapterid=295#1','',14,NULL,'',''),(13,'Количество равных из трех','https://informatics.msk.ru/mod/statements/view3.php?id=276&chapterid=296#1','',7,'pc8RmJLMyn4','https://www.patreon.com/posts/kolichestvo-iz-35039507',''),(14,'Квадратное уравнение','https://informatics.msk.ru/mod/statements/view3.php?id=276&chapterid=301#1','',9,NULL,'',''),(15,'Тип треугольника','https://informatics.msk.ru/mod/statements/view3.php?id=276&chapterid=302#1','',11,NULL,'',''),(16,'Коровы','https://informatics.msk.ru/mod/statements/view3.php?id=276&chapterid=303#1','',25,NULL,'',''),(17,'Билеты на метро','https://informatics.msk.ru/mod/statements/view3.php?id=276&chapterid=304#1','',22,NULL,'',''),(18,'Максимум из трех','https://informatics.msk.ru/mod/statements/view3.php?id=276&chapterid=294#1','',4,NULL,'',''),(19,'Этап жизни','','Ваша программа получает на вход возраст человека.Вам необходимо вывести на экран сообщение:\r\n- Младенец, если возраст меньше 2х лет;\r\n- Малыш, если возраст от 2, но меньше 4;\r\n- Ребенок, если возраст от 4 лет, но меньше 12;\r\n- Подросток, когда возраст от 12 лет, но меньше 19;\r\n- Взрослый человек, когда возраст от 19 лет, но меньше 65;\r\n- Пожилой человек, если возраст 65 и более.',14,NULL,'',''),(20,'Больше-меньше','https://acmp.ru/asp/do/index.asp?main=task&id_course=1&id_section=2&id_topic=29&id_problem=162','',3,NULL,'',''),(21,'Зарплата','https://acmp.ru/asp/do/index.asp?main=task&id_course=1&id_section=2&id_topic=29&id_problem=165','',11,NULL,'',''),(22,'Баскетбол','https://acmp.ru/asp/do/index.asp?main=task&id_course=1&id_section=2&id_topic=29&id_problem=166','',7,NULL,'',''),(23,'Четырехзначный палиндром','https://acmp.ru/asp/do/index.asp?main=task&id_course=1&id_section=2&id_topic=29&id_problem=275','',8,NULL,'',''),(24,'Торт','https://acmp.ru/asp/do/index.asp?main=task&id_course=1&id_section=2&id_topic=29&id_problem=167','',9,'sh5NmMJxkh0','https://boosty.to/egoroff_channel/posts/076755d1-724b-4016-9d73-faa745ed2ffc',''),(25,'Светофор','https://acmp.ru/asp/do/index.asp?main=task&id_course=1&id_section=2&id_topic=29&id_problem=169','',25,NULL,'',''),(26,'Координатные четверти','https://informatics.msk.ru/mod/statements/view3.php?id=276&chapterid=266','',12,NULL,'',''),(27,'A. Мишка и старший брат','http://codeforces.com/problemset/problem/791/A','',10,NULL,'',''),(28,'A. Ваня и кубики','http://codeforces.com/problemset/problem/492/A','',20,'46D3IFUfnSs','https://www.patreon.com/posts/razbor-zadachi-i-38406721',''),(29,'A. Вася и носки','http://codeforces.com/problemset/problem/460/A','',15,'4JrtXFnaix0','https://www.patreon.com/posts/vasia-i-noski-35228984',''),(30,'Список квадратов','https://informatics.msk.ru/mod/statements/view.php?id=249','',5,NULL,'',''),(31,'Ряд чисел 1 (while)','','Вывести на экран все числа от 50 до 150 включительно с помощью цикла while.',2,NULL,'',''),(32,'Ряд чисел 2 (while)','','Вывести на экран при помощи цикла while следующий ряд чисел:\r\n13, 20, 27 ...., 349.',3,NULL,'',''),(33,'Поехали','','Напишите программу, которая при помощи цикла while сделает обратный отсчет от 15 до 0 (включительно) и затем выведет  \"Поехали!\" в самом конце.',4,NULL,'',''),(34,'Утренняя пробежка','https://informatics.msk.ru/mod/statements/view3.php?id=249&chapterid=3062','',9,'XghXfzqyvCg','https://www.patreon.com/posts/razbor-zadachi-36209526',''),(35,'Жизнь без нулей','http://codeforces.com/problemset/problem/75/A','',15,'ODk-pRJnQ4U','https://www.patreon.com/posts/razbor-zadachi-36670543',''),(36,'Расставить звездочки. Рекурсия','https://informatics.msk.ru/mod/statements/view3.php?id=26735&chapterid=113655#1','',22,NULL,'',''),(37,'Зеркальная строка. Рекурсия','https://informatics.msk.ru/mod/statements/view3.php?id=26735&chapterid=113657#1','',25,'WDV3VHBd8Xs','https://www.patreon.com/posts/reshenie-zadachi-36249593',''),(38,'Нумеролог (acmp № 95)','https://acmp.ru/index.asp?main=task&id_task=95','',23,'Q7NS806dEt8','https://www.patreon.com/posts/razbor-zadachi-38410400',''),(39,'Делаем срезы','https://informatics.msk.ru/mod/statements/view.php?id=3863','',5,NULL,'',''),(40,'Количество слов','https://informatics.msk.ru/mod/statements/view3.php?id=3863&chapterid=3736','',5,NULL,'',''),(41,'Две половинки','https://informatics.msk.ru/mod/statements/view3.php?id=3863&chapterid=3737','',20,NULL,'',''),(42,'Переставить два слова','https://informatics.msk